head.script:
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gIsurCd;
scwin.gActTpCd;
scwin.gSeq;
scwin.gActTpCd;
scwin.gApprovStatCd;
scwin.regMode; // 'REG', 'MOD'
scwin.gComAbbrv;
scwin.pageUrl;
scwin.pageTitle;
scwin.pageW;
scwin.pageH;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.libRoundPanel.PanelToGroupBox(panel_1);
        await scwin.setCode();

        // 회사정보 로딩
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37700.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37700.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_List.errorMsg) {
            await $c.win.alert(dts_List.errorMsg);
        } else {
            $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37700.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37700.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        scwin.gSeq = dts_List.getCellData(Number(row), "CPOC_SEQ");
        scwin.gIsurCd = dts_List.getCellData(Number(row), "ISUR_CD");
        scwin.gActTpCd = dts_List.getCellData(Number(row), "CPOC_ACT_TP_CD");
        scwin.gApprovStatCd = dts_List.getCellData(Number(row), "CPOC_APPROV_STAT_CD");
        if (scwin.gApprovStatCd === "10") {
            scwin.regMode = 'MOD'; // 수정 및 검토모드

        } else if (scwin.gApprovStatCd === "20") {
            scwin.regMode = 'APP'; // 승인모드

        } else {
            scwin.regMode = 'VIEW'; // 승인완료모드

        }

        // 지정
        if (scwin.gActTpCd === '1') {
            scwin.pageUrl = '/dsclmgt/ULDSTF37701.gfm';
            scwin.pageTitle = '지정';
            scwin.pageW = '660';
            scwin.pageH = '350';

            // 지정사유변경

        } else if (scwin.gActTpCd === '2') {
            scwin.pageUrl = '/dsclmgt/ULDSTF37702.gfm';
            scwin.pageTitle = '지정사유변경';
            scwin.pageW = '660';
            scwin.pageH = '480';
            // 지정해제

        } else if (scwin.gActTpCd === '3') {
            scwin.pageUrl = '/dsclmgt/ULDSTF37701.gfm';
            scwin.pageTitle = '지정해제';
            scwin.pageW = '660';
            scwin.pageH = '350';
        }
        if (colid === "CPOC_DESIGN_RSN_NM") {
            // 승인상태 클릭 시
            await $c.frame.CreateDialogFrame("wndDiscls", scwin.pageUrl, "확인절차 대상법인 " + scwin.pageTitle, 300, 220, scwin.pageW, scwin.pageH, "window");
        }
        if (colid === "COM_ABBRV") {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37700.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name cmb_DEP_CD_onselchange
 * @description cmb_DEP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_DEP_CD_onselchange = function() {
    try {
        scwin.gDepCd = cmb_DEP_CD.getValue(); // ;.ValueOfIndex("VALUE", cmb_DEP_CD.Index);

        dts_EMP_NO.UseFilter = true;
        dts_EMP_NO.Filter();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37700.cmb_DEP_CD_onselchange" });
    }
};

/**
 * @method
 * @name dts_EMP_NO_OnFilter
 * @description EMP NO On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_EMP_NO_OnFilter = function(row) {
    try {
        if (scwin.gDepCd === "") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_EMP_NO.getCellData(row, "dep_cd") === scwin.gDepCd ||
                dts_EMP_NO.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37700.dts_EMP_NO_OnFilter" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37700.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37700.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37700.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37700.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37700.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37700.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37700.txb_isur_cd_onfocus" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37700.txb_isur_cd_onkeyup" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37700.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37700.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name img_FromCal_onclick
 * @description img_FromCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_FromCal_onclick = function() {
    try {
        popUpCalendar2(edt_SchDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37700.img_FromCal_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37700.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF37700.xml', SCREN_PROCS_TP_CD_07, '');
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "확인절차 대상법인 지정/지정해제", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF37700.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    try {
        scwin.regMode = "REG";
        if (txb_isur_cd.getValue() === '' || txb_com_abbrv.getValue() === '') {
            await $c.win.alert("확인절차 대상법인을 선택해 주세요.");
            txb_isur_cd.focus();
            return true;
        }
        if (cmb_ActTpCd.getValue() === '') {
            await $c.win.alert("조치구분을 선택해 주세요.");
            cmb_ActTpCd.focus();
            return true;
        }
        scwin.gIsurCd = txb_isur_cd.getValue();
        scwin.gComAbbrv = txb_com_abbrv.getValue();
        scwin.gActTpCd = cmb_ActTpCd.getValue();

        // 지정
        if (cmb_ActTpCd.getValue() === '1') {
            scwin.pageUrl = '/dsclmgt/ULDSTF37701.gfm';
            scwin.pageTitle = '지정';
            scwin.pageW = '660';
            scwin.pageH = '350';

            // 지정사유변경

        } else if (cmb_ActTpCd.getValue() === '2') {
            scwin.pageUrl = '/dsclmgt/ULDSTF37702.gfm';
            scwin.pageTitle = '지정사유변경';
            scwin.pageW = '660';
            scwin.pageH = '480';
            // 지정해제

        } else if (cmb_ActTpCd.getValue() === '3') {
            scwin.pageUrl = '/dsclmgt/ULDSTF37701.gfm';
            scwin.pageTitle = '지정해제';
            scwin.pageW = '660';
            scwin.pageH = '350';
        }

        // 확인절차 대상법인 지정 처리 체크
        if (await scwin.checkConfrmProcsStat(scwin.gIsurCd, scwin.gActTpCd) === false) {
            cmb_ActTpCd.focus();
            return;
        }
        await scwin.search();
        await $c.frame.CreateDialogFrame("wndDiscls", scwin.pageUrl, "확인절차 대상법인 " + scwin.pageTitle, 300, 220, scwin.pageW, scwin.pageH, "window");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37700.btn_New_onclick" });
    }
};

/**
 * @method
 * @name trs_check_OnSuccess
 * @description check On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_check_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "등록"));
        parent_function_call();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37700.trs_check_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_check_OnFail
 * @description check On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_check_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "등록"));
        await $c.win.alert(trs_insert.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37700.trs_check_OnFail" });
    }
};

/**
 * @method
 * @name btn_reflect_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_reflect_onclick = async function() {
    try {
        await scwin.updateExmptObjDisclsYn();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37700.btn_reflect_onclick" });
    }
};

/**
 * @method
 * @name trs_reflect_OnSuccess
 * @description reflect On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_reflect_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "등록"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37700.trs_reflect_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_reflect_OnFail
 * @description reflect On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_reflect_OnFail = async function() {
    try {
        // alert( getMessageParam("MSG-A002", "등록") );
        await $c.win.alert(trs_reflect.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF37700.trs_reflect_OnFail" });
    }
};

/**
 * @method
 * @name dts_reflect_OnLoadCompleted
 * @description dts_reflect 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_reflect_OnLoadCompleted = function(rowcount) {

};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description 페이지 로딩 시 필요한 변수 초기화
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_EMP_NO",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_EMP_NO=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_DEP_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_DEP_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions3 = {
        id : "sbm_dts_reflect",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_reflect=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_reflect.insertRow();

    // 조회일자 오늘로 셋팅
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SchDate.setValue("");
    // edt_SchDate.Text = vCurDate;

    // 부서코드 로그인 사용자 부서로 셋팅
    cmb_DEP_CD.setValue(js_dep_cd);
    if (cmb_DEP_CD.getValue() === '') {
        cmb_DEP_CD.setSelectedIndex(0);
    }
    if (scwin.gDepCd === 'ZSYS') {
        btn_reflect.show("");
    } else {
        btn_reflect.hide();
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const vISUR_CD = txb_isur_cd.getValue();
    const vDEP_CD = cmb_DEP_CD.getValue();
    const vEMP_NO = cmb_EMP_NO.getValue();
    const vSTAT_CD = cmb_stat_cd.getValue();
    const vENFORCE_DD = edt_SchDate.getValue();
    if (scwin.gLdMktTp === '9') {
        scwin.gLdMktTp = '1';
    } else {
        scwin.gLdMktTp = scwin.gLdMktTp;
    }
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&CPOC_APPROV_STAT_CD=" + $c.stf.trim(vSTAT_CD);
